class Solution {
  public int kthSmallest(int[][] matrix, int k) {
    int n = matrix.length, lo = matrix[0][0], hi = matrix[n - 1][n - 1];
    // smallest value v with at least k entries <= v
    while (lo < hi) {
      int mid = lo + (hi - lo) / 2, count = 0;
      for (int r = n - 1, c = 0; r >= 0 && c < n; ) {
        if (matrix[r][c] <= mid) {
          count += r + 1;
          c++;
        } else r--;
      }
      if (count < k) lo = mid + 1;
      else hi = mid;
    }
    return lo;
  }
}
